{
  "message": "I've been a loyal customer but I have a competitive offer that's very attractive. To keep me, I'd need a significant package: 40% discount, $100 credit, a premium upgrade, and I want to stay on monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 40,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Starting with the maximum value package (36) to anchor high, leaving room for concessions while still above my walk-away value of 28."
}

{
  "message": "I appreciate the offer, but the discount is too low compared to my alternative. I'd need at least a 30% discount and a $100 credit along with the premium upgrade to stay on monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Proposing a package worth 32 (30% discount = 12, $100 credit = 8, premium upgrade = 12), which exceeds my walk-away value of 28 and is a reasonable compromise from my initial 40% request."
}

{
  "message": "I appreciate you moving to 20% and $50, but my alternative is still significantly better. To make staying worthwhile, I need at least a 30% discount and a $100 credit along with the premium upgrade on monthly billing. Can you do that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "This package gives me a value of 32, which exceeds my outside option of 28, and I have turns left to negotiate if they counter."
}

{
  "message": "That works for me. I'll accept the 30% discount, $50 credit, and premium upgrade on monthly billing.",
  "move": {
    "type": "accept",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "The proposal matches the value of my alternative (28), and the agent has indicated this is the maximum discount and credit available on monthly billing, so no better deal is possible."
}
